// 이번 단계(depth)에서 방문할 URL 목록을 정리합니다.
// 시트 1에서 처음 호출되면 depth=0 (DDG 검색 URL), 재귀 호출이면 depth>=1
const MAX_DEPTH = 6;        // 비상 브레이크: 정상적인 양판점이면 닿지 않는 깊이

const items = $input.all().map(i => i.json).filter(j => j && j.url && !j._noop);
if (!items.length) return [];

// "euro.com.pl"처럼 https:// 없이 오면 상대경로 링크를 못 붙이므로 보정
items.forEach(j => {
  j.url = String(j.url).trim();
  if (!/^https?:\/\//i.test(j.url)) j.url = 'https://' + j.url.replace(/^\/+/, '');
});

const first = items[0];
const depth = Number(first.depth || 0);
if (depth > MAX_DEPTH) return [];

const visited = new Set(first.visited || []);

// 검색 모드: 영문+숫자가 섞인 5자 이상 토큰(모델 코드)이 있으면 MODEL, 아니면 CATEGORY(제품군)
const kwSrc = String(first.original_keyword || first.keyword || '');
const isModelCode = kwSrc.split(/\s+/).some(t => t.length >= 5 && /[A-Za-z]/.test(t) && /\d/.test(t));
const searchMode = first.search_mode || (isModelCode ? 'MODEL' : 'CATEGORY');
// 한 단계에서 여는 최대 페이지 수 (크레딧 보호). 제품군은 여러 브랜드를 넓게 봐야 해서 더 많이
const MAX_PER_LEVEL = searchMode === 'CATEGORY' ? 20 : 10;

// 기준 도메인: DDG URL의 site:도메인, 없으면 URL 호스트
let rootDomain = first.root_domain || '';
if (!rootDomain) {
  try {
    const m = decodeURIComponent(first.url).match(/site:([^\s+&]+)/);
    rootDomain = (m ? m[1] : ((String(first.url).match(/^https?:\/\/([^\/?#:]+)/i) || [])[1] || '')).replace(/^www\./, '');
  } catch (e) {
    rootDomain = '';
  }
}

const picked = [];
for (const j of items) {
  const url = String(j.url).trim();
  if (visited.has(url) && !j.retry) continue;   // 차단 재시도(retry>0)는 다시 방문 허용
  visited.add(url);
  picked.push({ ...j, url });
  if (picked.length >= MAX_PER_LEVEL) break;
}

const visitedArr = [...visited];
return picked.map(j => ({
  json: {
    url: j.url,
    depth,
    root_domain: rootDomain,
    keyword: j.keyword || '',
    original_keyword: j.original_keyword || j.keyword || '',
    category: j.category || 'E-commerce',
    site_name: j.site_name || rootDomain || 'External_Site',
    country: j.country || '',
    search_mode: searchMode,
    review_hops: Number(j.review_hops || 0),
    retry: Number(j.retry || 0),
    // 시작 URL이 실패하면 순서대로 시도할 대체 URL (시트 1: [홈페이지, DDG 검색])
    fallback_urls: Array.isArray(j.fallback_urls) ? j.fallback_urls : (j.fallback_url ? [j.fallback_url] : []),
    visited: visitedArr
  }
}));

// 스크래핑 결과 정리. DDG 검색결과는 AI 없이 코드로 링크를 뽑습니다.
const src = $('입력 정리').item.json;
const md = $json.markdown || '';
// ScrapingAnt 마크다운은 80자 근처에서 줄을 바꾸면서 링크 URL 중간에도 줄바꿈을 넣음 → (…) 안의 줄바꿈 제거
const mdn = md.replace(/\]\(([^)]*)\)/g, (m, u) => '](' + u.replace(/\s*\n\s*/g, '') + ')');
const isDdg = src.url.includes('duckduckgo.com');

let ddgLinks = [];
if (isDdg) {
  ddgLinks = [...mdn.matchAll(/uddg=([^&)\s]+)/g)]
    .map(m => { try { return decodeURIComponent(m[1]); } catch (e) { return ''; } })
    .filter(u => u.startsWith('http') && !u.includes('duckduckgo.com/y.js'));  // 광고 제외
  ddgLinks = [...new Set(ddgLinks)];
}

// 봇 차단/캡차 페이지 감지 (ceneo 캡차, Cloudflare "잠시만 기다리십시오" 등). 이런 페이지를 AI에 주면 링크를 지어냄
const BLOCK_RE = /captcha|nie jesteś robotem|po drugiej stronie siedzi człowiek|przejdź dalej|just a moment|verify you are human|are you a robot|access denied|attention required|cf-chl|unusual traffic|bitte bestätigen|robot check|bots use duckduckgo|search was made by a human|select all squares|żądanie zostało zablokowane|request (has been|was) blocked/i;
const HARD_BLOCK_RE = /cf-chl|challenge-platform|just a moment|checking your browser|verify you are human|po drugiej stronie siedzi człowiek|nie jesteś robotem|captcha\/add|żądanie zostało zablokowane/i;
const blocked = !!md && ((md.length < 5000 && BLOCK_RE.test(md)) || HARD_BLOCK_RE.test(md.slice(0, 20000)));
const scrapeError = !md
  ? 'SCRAPE_FAIL: ' + String($json.error?.message || $json.message || 'empty markdown').slice(0, 200)
  : (blocked ? 'BLOCKED: 봇 차단/캡차 페이지' : null);

// 링크는 AI가 지어내지 않도록 코드로 전부 뽑아서 번호를 붙여 보여줍니다. (AI는 번호만 고름)
const MAX_LINKS = 200;
const origin = (String(src.url).match(/^https?:\/\/[^\/?#]+/i) || [''])[0];
const root = String(src.root_domain || '').replace(/^www\./, '');
const JUNK = /login|logowanie|rejestr|koszyk|cart|basket|checkout|account|konto|privacy|polityka|regulamin|cookie|facebook|instagram|youtube|twitter|tiktok|pinterest|linkedin|mailto:|tel:|javascript:|\.(jpe?g|png|gif|webp|svg|css|js|ico)(\?|$)/i;
const kwParts = String(src.keyword + ' ' + src.original_keyword).toLowerCase()
  .split(/[\s\-_+,]+/).filter(t => t.length >= 4).map(t => t.slice(0, 5));

function absUrl(u) {
  u = String(u).trim().split('#')[0];
  if (/^https?:\/\//i.test(u)) return u;
  if (u.startsWith('//')) return 'https:' + u;
  if (u.startsWith('/') && origin) return origin + u;
  return '';
}

const linkMap = new Map();   // url -> { text, pos }
if (!isDdg && !scrapeError) {
  // 1) [텍스트](url) 형태  2) 이미지로 감싼 링크 등 나머지 ](url) 형태
  for (const m of mdn.matchAll(/(!?)\[([^\[\]]*)\]\(\s*<?([^)\s>]+)/g)) {
    if (m[1] === '!') continue;
    const url = absUrl(m[3]);
    if (url && !linkMap.has(url)) linkMap.set(url, { text: m[2].replace(/\s+/g, ' ').trim(), pos: m.index });
  }
  for (const m of mdn.matchAll(/\]\(\s*<?([^)\s>]+)/g)) {
    const url = absUrl(m[1]);
    if (url && !linkMap.has(url)) linkMap.set(url, { text: '', pos: m.index });
  }
}

const here = String(src.url).split('#')[0];
const candidates = [...linkMap.entries()]
  .filter(([url]) => url !== here && !JUNK.test(url))
  .filter(([url]) => {
    const host = ((url.match(/^https?:\/\/([^\/?#:]+)/i) || [])[1] || '').toLowerCase().replace(/^www\./, '');
    return host && (!root || host.endsWith(root));
  })
  .map(([url, v]) => {
    const t = (v.text + ' ' + url).toLowerCase();
    let score = 0;
    if (kwParts.some(k => t.includes(k))) score += 3;                    // 찾는 제품 관련
    if (/\/\d{5,}/.test(url)) score += 2;                                 // 제품 ID 경로
    if (/opini|review|recenz|bewert|avis|rating|ocen/i.test(t)) score += 2;  // 리뷰 관련
    if (/[?&;](page|p|strona)=?\d|;\d+-\d+\.htm/i.test(url)) score += 1;   // 페이지네이션
    return { url, text: v.text, pos: v.pos, score };
  })
  .sort((a, b) => (b.score - a.score) || (a.pos - b.pos))
  .slice(0, MAX_LINKS);

const linkList = candidates.map(c => c.url);
const pageLinks = candidates
  .map((c, i) => i + '. ' + (c.text.slice(0, 70) || '(이미지/텍스트 없음)') + ' | ' + c.url.replace(origin, ''))
  .join('\n');

// 본문 정리: 이미지 제거, 링크는 텍스트만 남김(URL이 대부분의 분량이라 이것만으로 크게 줄어듦)
// 링크가 3개 이상 붙어 있는 줄(메가 메뉴/푸터)만 통째로 뺌 → 짧은 리뷰("Polecam!" 등)는 지우지 않음
const content = mdn.split('\n')
  .map(line => {
    const linkCount = (line.match(/\]\(/g) || []).length;
    if (linkCount >= 3) return null;
    return line
      .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
      .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
      .replace(/\s+/g, ' ').trim();
  })
  .filter(l => l !== null)
  .join('\n')
  .replace(/\n{3,}/g, '\n\n');

// AI에 넘길 본문: 길면 앞부분 + 리뷰 구간(opinie/review 등이 처음 나오는 곳부터)을 이어 붙임
const BODY_LIMIT = 30000;
let body = content;
if (content.length > BODY_LIMIT) {
  const head = content.slice(0, 8000);
  const rest = content.slice(8000);
  const idx = rest.search(/opini|recenz|review|bewert|avis|ocen[ay]|gwiazd|stars?\b|rating/i);
  body = head + '\n...\n' + (idx >= 0 ? rest.slice(Math.max(0, idx - 500)) : rest).slice(0, BODY_LIMIT - 8000);
}

return {
  json: {
    ...src,
    is_ddg: isDdg,
    ddg_links: ddgLinks,
    scrape_error: scrapeError,
    md_len: md.length,                                   // 차단 판정 검증용
    md_head: scrapeError ? md.slice(0, 200) : content.slice(0, 300),  // 실제 받은 내용 앞부분 (차단이면 원문, 아니면 메뉴 뺀 본문)
    link_list: linkList,
    page_links: pageLinks || '(링크 없음)',
    page_markdown: isDdg
      ? '(검색엔진 결과 페이지 - 판정 불필요. IRRELEVANT로 응답)'
      : scrapeError
        ? '(수집 실패/차단 페이지 - 판정 불필요. IRRELEVANT로 응답)'
        : (body || '(빈 페이지)')
  }
};

// AI 판정 결과를 리뷰 행(reviews)과 다음 단계 링크(next)로 나눕니다.
// 페이지당 다음 링크 수 / 제품당 리뷰 페이지를 몇 쪽까지 따라갈지 (모드별)
const LIMITS = {
  MODEL:    { list: 3,  review: 3, reviewHops: 5 },   // 모델 하나를 깊게
  CATEGORY: { list: 10, review: 1, reviewHops: 2 }    // 여러 제품을 넓게, 제품당 리뷰 1~2쪽
};
const pages = $('페이지 준비').all().map(i => i.json);

function makeHash(str) {
  let h = 0;
  const s = String(str).trim();
  for (let i = 0; i < s.length; i++) { h = ((h << 5) - h) + s.charCodeAt(i); h |= 0; }
  return Math.abs(h).toString(36);
}

function normalize(link, base) {
  if (typeof link !== 'string') return '';
  let u = link.trim().replace(/^<|>$/g, '');
  const md = u.match(/\]\((.+)\)$/);          // [text](url) 형태로 오면 url만
  if (md) u = md[1];
  const uddg = u.match(/uddg=([^&]+)/);
  if (uddg) { try { u = decodeURIComponent(uddg[1]); } catch (e) {} }
  // n8n Code 노드 샌드박스에는 URL 객체가 없을 수 있어서 정규식으로 처리
  u = u.split('#')[0];
  if (/^https?:\/\//i.test(u)) return u;
  if (u.startsWith('//')) return 'https:' + u;
  const origin = (String(base).match(/^https?:\/\/[^\/?#]+/i) || [''])[0];
  if (origin && u.startsWith('/')) return origin + u;
  return '';
}

function hostOf(u) {
  const m = String(u).match(/^https?:\/\/([^\/?#:]+)/i);
  return m ? m[1].toLowerCase() : '';
}

const reviews = [];
const nextMap = new Map();
const log = [];

$input.all().forEach((item, i) => {
  const p = pages[i];
  if (!p) return;

  let type = 'IRRELEVANT';
  let revs = [];
  let links = [];
  let sellers = [];
  const lim = LIMITS[p.search_mode] || LIMITS.CATEGORY;

  if (p.scrape_error) {
    type = p.scrape_error.startsWith('BLOCKED') ? 'BLOCKED' : 'SCRAPE_FAIL';   // AI 응답은 믿지 않음
  } else if (!p.is_ddg && item.json.error) {
    type = "AI_ERROR";   // OpenAI 호출 실패 (재시도 3회 후)
  } else if (p.is_ddg) {
    type = 'SEARCH';
    // 기사/랭킹/블로그보다 제품 페이지(숫자 ID 경로)를 먼저 방문
    const isArticle = u => /magazyn|blog|poradnik|artyku|ranking|news|guide|ratgeber|forum/i.test(u);
    const hasId = u => /\/\d{5,}/.test(u);
    links = [...(p.ddg_links || [])].sort((a, b) => (isArticle(a) - isArticle(b)) || (hasId(b) - hasId(a)));
  } else {
    const raw = String(item.json.text || item.json.output || '{}');
    try {
      const m = raw.match(/\{[\s\S]*\}/);
      const parsed = JSON.parse(m ? m[0] : raw);
      type = String(parsed.page_type || 'IRRELEVANT').toUpperCase();
      revs = Array.isArray(parsed.reviews) ? parsed.reviews : [];
      links = Array.isArray(parsed.next_links) ? parsed.next_links : [];
      // AI는 [링크 목록]의 번호를 줌 → 실제 URL로 변환 (혹시 URL을 주면 그대로)
      const list = p.link_list || [];
      links = links.map(l => /^\d+$/.test(String(l).trim()) ? list[Number(l)] : l).filter(Boolean);
      sellers = Array.isArray(parsed.sellers) ? parsed.sellers.filter(s => typeof s === 'string' && s.trim()) : [];
    } catch (e) {
      type = 'PARSE_ERROR';
    }
  }

  for (const v of revs) {
    if (!v || !v.content) continue;
    reviews.push({
      voc_id: `EXT_${makeHash(p.url + String(v.content).substring(0, 120))}`,
      source_site: p.site_name || 'External_Site',
      category: p.category || 'E-commerce',
      content_type: v.content_type || 'REVIEW',
      content: String(v.content),
      parent_id: p.url,
      published_at: v.published_at || null,
      sellers                                   // 가격비교 사이트의 판매처 이름 (확인용, DB 칼럼 없음)
    });
  }

  const visited = new Set(p.visited || []);
  let added = 0;
  const skip = { bad_url: 0, visited: 0, other_domain: [] };  // 링크가 왜 탈락했는지 (디버깅용)
  let root = String(p.root_domain || '').replace(/^www\./, '');
  if (root.includes('duckduckgo')) root = '';  // site: 파싱 실패로 DDG 호스트가 들어오면 모든 링크가 탈락하므로 무시
  const isProduct = type === 'PRODUCT';
  const hops = Number(p.review_hops || 0) + (isProduct ? 1 : 0);
  let linkLimit = p.is_ddg ? 8 : (isProduct ? lim.review : lim.list);
  if (isProduct && hops > lim.reviewHops) linkLimit = 0;   // 리뷰 페이지를 충분히 따라감
  if (!['IRRELEVANT', 'PARSE_ERROR', 'BLOCKED', 'SCRAPE_FAIL', 'AI_ERROR'].includes(type)) {
    for (const l of links) {
      if (added >= linkLimit) break;
      const url = normalize(l, p.url);
      if (!url.startsWith('http')) { skip.bad_url++; continue; }
      if (visited.has(url) || nextMap.has(url)) { skip.visited++; continue; }
      let host = '';
      host = hostOf(url).replace(/^www\./, '');
      if (!host) { skip.bad_url++; continue; }
      if (host.includes('duckduckgo')) { skip.other_domain.push(host); continue; }  // DDG 광고/내부 링크
      if (root && !host.endsWith(root)) { skip.other_domain.push(host); continue; }  // 양판점 밖으로 나가지 않음
      nextMap.set(url, {
        url,
        depth: p.depth + 1,
        root_domain: root || host,
        keyword: p.keyword,
        original_keyword: p.original_keyword,
        category: p.category,
        site_name: p.site_name,
        country: p.country,
        search_mode: p.search_mode,
        review_hops: hops,
        visited: p.visited
      });
      added++;
    }
  }

  const MAX_RETRY = 2;
  const failed = type === 'BLOCKED' || type === 'SCRAPE_FAIL';
  const fb = Array.isArray(p.fallback_urls) ? p.fallback_urls : [];
  const canRetry = type === 'BLOCKED' || !fb.length;   // 검색 URL 형식 오류(404 등)는 재시도 말고 바로 다음 대체 URL로
  let fellBack = false;
  if (failed && canRetry && Number(p.retry || 0) < MAX_RETRY && !nextMap.has(p.url)) {
    nextMap.set(p.url, {
      url: p.url,
      depth: p.depth,                 // 같은 단계로 다시 시도 (깊이 제한에 안 걸리게)
      root_domain: p.root_domain,
      keyword: p.keyword,
      original_keyword: p.original_keyword,
      category: p.category,
      site_name: p.site_name,
      country: p.country,
      search_mode: p.search_mode,
      review_hops: p.review_hops,
      retry: Number(p.retry || 0) + 1,
      fallback_urls: fb,
      visited: p.visited
    });
  } else if (fb.length && (failed || added === 0) && !nextMap.has(fb[0])) {
    // 시작 URL이 막혔거나 결과(다음 링크)가 없으면 다음 대체 URL로 (홈페이지 → DDG 순)
    nextMap.set(fb[0], {
      url: fb[0],
      depth: p.depth,
      root_domain: p.root_domain,
      keyword: p.keyword,
      original_keyword: p.original_keyword,
      category: p.category,
      site_name: p.site_name,
      country: p.country,
      search_mode: p.search_mode,
      review_hops: p.review_hops,
      retry: 0,
      fallback_urls: fb.slice(1),
      visited: p.visited
    });
    fellBack = true;
  }

  log.push({ retry: Number(p.retry || 0), fallback_to_ddg: fellBack || undefined,  depth: p.depth, url: p.url, type, reviews: revs.length, next_links: added, error: p.scrape_error, md_len: p.md_len, md_head: p.md_head, link_count: (p.link_list || []).length, root_domain: p.root_domain, candidates: links.length, mode: p.search_mode, sellers: sellers.length, skip });
});

return [{ json: { reviews, next: [...nextMap.values()], log } }];

// 다음 단계로 넘길 링크를 아이템으로 펼칩니다. 없으면 재귀 호출이 즉시 끝나도록 _noop 1개.
const next = $input.first().json.next || [];
if (!next.length) return [{ json: { _noop: true } }];
return next.map(json => ({ json }));

// 이번 단계에서 얻은 리뷰 + 하위 단계(재귀)에서 얻은 리뷰를 합쳐 반환합니다.
// 크롤링 로그(_crawl_log)도 같이 올려서 시트 1/최상위 실행에서 전체 경로를 볼 수 있게 합니다.
// (시트 1은 voc_id + content가 있는 행만 쓰므로 로그 행은 자동으로 무시됨)
const own = $('결과 정리').first().json;
const childItems = $input.all().map(i => i.json).filter(j => j && Object.keys(j).length);

const uniq = new Map();
for (const r of [...(own.reviews || []), ...childItems.filter(j => j.voc_id && j.content)]) uniq.set(r.voc_id, r);

const logs = [
  ...(own.log || []).map(l => ({ _crawl_log: true, ...l, skip: undefined })),
  ...childItems.filter(j => j._crawl_log)
];

return [...uniq.values(), ...logs].map(json => ({ json }));
